fn check_disconnected(n: i8, m: i8, horizontal: &Vec<char>, vertical: &Vec<char>) -> bool {
    // Convert sizes to usize for indexing
    let n = n as usize;
    let m = m as usize;

    // Extract the four corner arrows
    let h_first = horizontal[0];
    let h_last = horizontal[n - 1];
    let v_first = vertical[0];
    let v_last = vertical[m - 1];

    // Check the four disconnection conditions
    (h_first == '>' && v_first == 'v')
        || (h_first == '<' && v_last == 'v')
        || (h_last == '>' && v_first == '^')
        || (h_last == '<' && v_last == '^')
}

fn solve(n: i8, m: i8, horizontal: Vec<char>, vertical: Vec<char>) -> Vec<char> {
    if check_disconnected(n, m, &horizontal, &vertical) {
        vec!['N', 'O', '\n']
    } else {
        vec!['Y', 'E', 'S', '\n']
    }
}

